    i = int(i)
    if i not in comida:
        comida[i] = 0
    comida[i] += 1

q = PriorityQueue()

for i in comida:
    q.put((-comida[i], i))


def last_n_days(days, q):
    qcopy = PriorityQueue()
    qcopy.queue = copy.deepcopy(q.queue)

    last = 0

    if days == 0:
        return -qnt_pessoas

    while not qcopy.empty():
        entry = qcopy.get()
        last += (-entry[0])//days

    return last - qnt_pessoas


def busca_binaria(left, right):
    best = 0
    while left <= right:
        mid = (left + right) // 2
        if mid == 0:
            left = 1
            continue

        res = last_n_days(mid, q)

        if res >= 0:
            best = mid
            left = mid + 1
        else:
            right = mid - 1

    return best


